func (v DataValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	items := types.ListValueMust(
		ItemsType{
			basetypes.ObjectType{
				AttrTypes: ItemsValue{}.AttributeTypes(ctx),
			},
		},
		v.Items.Elements(),
	)

	if v.Items.IsNull() {
		items = types.ListNull(
			ItemsType{
				basetypes.ObjectType{
					AttrTypes: ItemsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	if v.Items.IsUnknown() {
		items = types.ListUnknown(
			ItemsType{
				basetypes.ObjectType{
					AttrTypes: ItemsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	var pagination basetypes.ObjectValue

	if v.Pagination.IsNull() {
		pagination = types.ObjectNull(
			PaginationValue{}.AttributeTypes(ctx),
		)
	}

	if v.Pagination.IsUnknown() {
		pagination = types.ObjectUnknown(
			PaginationValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Pagination.IsNull() && !v.Pagination.IsUnknown() {
		pagination = types.ObjectValueMust(
			PaginationValue{}.AttributeTypes(ctx),
			v.Pagination.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"items": basetypes.ListType{
			ElemType: ItemsValue{}.Type(ctx),
		},
		"pagination": basetypes.ObjectType{
			AttrTypes: PaginationValue{}.AttributeTypes(ctx),
		},
		"total": basetypes.Int64Type{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"items":      items,
			"pagination": pagination,
			"total":      v.Total,
		})

	return objVal, diags
}

func (v DataValue) Equal(o attr.Value) bool {
	other, ok := o.(DataValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Items.Equal(other.Items) {
		return false
	}

	if !v.Pagination.Equal(other.Pagination) {
		return false
	}

	if !v.Total.Equal(other.Total) {
		return false
	}

	return true
}

